    /// T362: total physical memory in bytes, for the resume-surface fleet-
    /// memory line.  macOS: `sysctl -n hw.memsize`; Linux: /proc/meminfo
    /// `MemTotal:`.  Returns null when the reading is unavailable so the
    /// resume surface degrades gracefully (no fleet-memory line) rather than
    /// failing to compose.
    fn hostMemBytes(io: std.Io) ?u64 {
        if (@import("builtin").os.tag == .linux) {
            const content = std.Io.Dir.cwd().readFileAlloc(io, "/proc/meminfo", alloc, .unlimited) catch return null;
            defer alloc.free(content);
            var lines = std.mem.splitScalar(u8, content, '\n');
            while (lines.next()) |line| {
                if (std.mem.startsWith(u8, line, "MemTotal:")) {
                    var tok = std.mem.tokenizeAny(u8, line, " \t");
                    _ = tok.next();
                    const num = tok.next() orelse return null;
                    const kb = std.fmt.parseInt(u64, num, 10) catch return null;
                    return kb * 1024;
                }
            }
            return null;
        }
        const out = runCommand(alloc, io, &.{ "sysctl", "-n", "hw.memsize" }) catch return null;
        defer if (@intFromPtr(out.ptr) != @intFromPtr("".ptr)) alloc.free(out);
        const s = std.mem.trim(u8, out, " \t\r\n");
        return std.fmt.parseInt(u64, s, 10) catch null;
    }

